import{_ as i,o as a,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Tailoring","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/professions/tailoring.md","filePath":"game-design/professions/tailoring.md"}'),l={name:"game-design/professions/tailoring.md"};function s(r,e,o,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="tailoring" tabindex="-1">Tailoring <a class="header-anchor" href="#tailoring" aria-label="Permalink to &quot;Tailoring&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; all mechanics, examples and technique paths below remain candidates. <strong>Implementation:</strong> no implementation of this redesign is established by this documentation batch. <strong>Availability:</strong> not established. <strong>Verification:</strong> documentation review only; no gameplay test. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/guide/professions/tailoring.html">Player-facing overview</a> · <a href="/Syrolands-Public/game-design/professions/profession-system.html">Profession System</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Purpose and profession loop <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Permalink to &quot;Purpose and profession loop&quot;">​</a></h2><p>Tailoring should be the profession of flexible materials:</p><ul><li>hides;</li><li>leather;</li><li>fur;</li><li>cloth;</li><li>fibers;</li><li>thread;</li><li>padding;</li><li>stitching;</li><li>flexible armor;</li><li>garments;</li><li>insulation;</li><li>fit;</li><li>textile treatments.</li></ul><p>Skinning should not necessarily be a standalone skill. Potential synergy:</p><ul><li>Tailoring -&gt; preserve/process hide;</li><li>Anatomy -&gt; where/how to cut;</li><li>Animal Lore -&gt; creature-specific knowledge.</li></ul><p>Creature corpses can yield different material zones/components. Damage method can affect hide quality:</p><ul><li>slashing can damage hide;</li><li>fire can burn it;</li><li>blunt damage may preserve surface better;</li></ul><p>etc.</p><h3 id="core-chain" tabindex="-1">Core chain <a class="header-anchor" href="#core-chain" aria-label="Permalink to &quot;Core chain&quot;">​</a></h3><p>Harvest -&gt; Preserve -&gt; Process -&gt; Grade -&gt; Cut -&gt; Assemble -&gt; Fit -&gt; Finish</p><h3 id="leather-processing-may-include" tabindex="-1">Leather processing may include <a class="header-anchor" href="#leather-processing-may-include" aria-label="Permalink to &quot;Leather processing may include&quot;">​</a></h3><ul><li>cleaning;</li><li>curing;</li><li>tanning;</li><li>treatment.</li></ul><p>Different tanning/treatment methods can create different material identities:</p><ul><li>firmer/durable;</li><li>softer/flexible;</li><li>weather-resistant;</li><li>alchemically treated.</li></ul><h3 id="fibers-cloth" tabindex="-1">Fibers/cloth <a class="header-anchor" href="#fibers-cloth" aria-label="Permalink to &quot;Fibers/cloth&quot;">​</a></h3><ul><li>flax;</li><li>cotton;</li><li>wool;</li><li>silk;</li><li>hemp;</li><li>fantasy fibers later.</li></ul><p>Possible weave identities:</p><ul><li>loose;</li><li>dense;</li><li>layered;</li><li>reinforced.</li></ul><p>Armor/clothing construction can conceptually use layers:</p><ul><li>outer;</li><li>structural;</li><li>padding;</li><li>lining.</li></ul><p>Cloth/leather armor can be meaningfully protective without acting like plate.</p><h3 id="field-utility" tabindex="-1">Field utility <a class="header-anchor" href="#field-utility" aria-label="Permalink to &quot;Field utility&quot;">​</a></h3><ul><li>fitting;</li><li>field stitching;</li><li>repair;</li><li>material assessment;</li><li>reduced penalties through correct adjustment/maintenance rather than flat +Armor.</li></ul><h3 id="fashion-and-status" tabindex="-1">Fashion and status <a class="header-anchor" href="#fashion-and-status" aria-label="Permalink to &quot;Fashion and status&quot;">​</a></h3><ul><li>cuts;</li><li>patterns;</li><li>trims;</li><li>dyes;</li><li>embroidery;</li><li>guild/cultural styles.</li></ul><p>Dyes can eventually connect to pigments, mordants and Alchemy, but keep first-pass complexity controlled.</p><h2 id="knowledge-and-specialization" tabindex="-1">Knowledge and specialization <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Permalink to &quot;Knowledge and specialization&quot;">​</a></h2><p><strong>Material/Tailoring Journal.</strong> Learn material zones, preservation, processing, cuts and construction. Functional fitting and fashion/status are both legitimate specialization directions.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Shared progression, production and economy <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Permalink to &quot;Shared progression, production and economy&quot;">​</a></h2><p>The <a href="/Syrolands-Public/game-design/characters/skills-and-skillcap.html">character skill framework</a> owns teaching and cap/gain direction. The <a href="/Syrolands-Public/game-design/professions/profession-system.html">Profession System</a> owns craft discovery, knowledge sharing, manual mastery, batch production, commissions and multidimensional reputation. Those rules are not independently redefined here. The <a href="/Syrolands-Public/game-design/items/itemization-and-craft-quality.html">quality specification</a> owns the shared result envelope and rare item properties.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Related skills and field interactions <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Permalink to &quot;Related skills and field interactions&quot;">​</a></h2><p>Anatomy may inform how/where to cut; Animal Lore may inform creature-specific harvesting; Tailoring preserves and processes the hide. Alchemy may provide treatments, pigments and mordants. These proposed roles do not redefine current Anatomy checks.</p><p><a href="/Syrolands-Public/game-design/creatures.html">Creature anatomy</a> · <a href="/Syrolands-Public/game-design/skills-and-knowledge.html">Anatomy and skill roles</a> · <a href="/Syrolands-Public/game-design/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/game-design/equipment-and-loot.html">Equipment and loot</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstraction and technical boundary <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Permalink to &quot;Abstraction and technical boundary&quot;">​</a></h2><p>Keep only state and feedback that support meaningful decisions. The <a href="/Syrolands-Public/game-design/professions/profession-system.html#performance-abstraction-and-authority">shared abstraction/authority constraints</a> and living-world architecture apply; persistence requires a separate technical design. Nothing here selects packet IDs, schemas, timers, UI assets or runtime algorithms.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Whether any separate skinning skill is needed; corpse-zone yield and damage history; preservation/tanning duration; fitting and protection tradeoffs; appearance versus functional layers; dye complexity and maintenance costs. Conceptual layers do not establish arbitrary legacy sprite/equipment support.</p><p>The <a href="/Syrolands-Public/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">shared reconciliation register</a> owns cross-system conflicts. Existing combat experiments and evidence do not validate this profession redesign.</p>',41)])])}const m=i(l,[["render",s]]);export{u as __pageData,m as default};
